impl Solution{pub fn exist(mut b:Vec<Vec<char>>,w:String)->bool{fn f(b:&mut Vec<Vec<char>>,i:i32,j:i32,w:&[u8],k:usize)->bool{if k==w.len(){return true}if i<0||j<0||i>=b.len()as i32||j>=b[0].len()as i32||b[i as usize][j as usize]as u8!=w[k]{return false}let c=b[i as usize][j as usize];b[i as usize][j as usize]='\0';let ok=f(b,i+1,j,w,k+1)||f(b,i-1,j,w,k+1)||f(b,i,j+1,w,k+1)||f(b,i,j-1,w,k+1);b[i as usize][j as usize]=c;ok}for i in 0..b.len(){for j in 0..b[0].len(){if f(&mut b,i as i32,j as i32,w.as_bytes(),0){return true}}}false}}
